adding:0 12px 12px}.workspace-view .token-section .section-actions{width:100%}.token-row{gap:8px}.token-description{flex-basis:100%}.workspace-view .account-card{padding:16px}}\n/* Board placement only: four columns above, order-first development below. */\n#board.board{grid-template-columns:repeat(4,minmax(0,1fr))}\n#board>.column[data-column=\"0\"]{grid-area:1 / 1}\n#board>.column[data-column=\"1\"]{grid-area:1 / 2}\n#board>.column[data-column=\"2\"]{grid-area:1 / 3}\n#board>.column[data-column=\"4\"]{grid-area:1 / 4}\n#board>.column[data-column=\"3\"]{grid-area:2 / 1 / auto / -1}\n</style></head><body>\n<header><button id=\"mode\" class=\"mode\" disabled>◉ 只读模式</button><div class=\"brand\"><span class=\"mark\" aria-hidden=\"true\">▦</span><div>告示板<span class=\"subtitle\">TEAM WORKSPACE</span></div></div><div class=\"header-actions\"><div class=\"identity-summary\" aria-live=\"polite\"><span id=\"actor\">正在确认身份</span><span id=\"permission-summary\">正在核对权限…</span></div><button id=\"authorize\">GitHub 登录</button><button id=\"logout\" hidden>退出授权</button></div></header>\n<main><section class=\"intro\" hidden><div><div class=\"eyebrow\">ONE TEAM. ONE PLACE.</div><h1>让每一件事，都有着落。</h1><p>从一个想法，到一次交付。团队的进展，在这里一起发生。</p></div><div id=\"stats\" class=\"stats\"></div></section>\n<nav aria-label=\"功能区\"><button class=\"tab active\" data-view=\"board\">协作告示板 <span>01</span></button><button class=\"tab\" data-view=\"accounts\" hidden>公有账号 <span>02</span></button><button class=\"tab\" data-view=\"manage\" hidden>权限管理 <span>03</span></button><div class=\"nav-tail\"><span class=\"live-dot\"></span><span id=\"sync-status\">连接中</span><button id=\"refresh\" title=\"刷新\">↻</button></div></nav>\n<div id=\"notice\" role=\"status\" aria-live=\"polite\"></div>\n<section id=\"board-view\" class=\"view\"><div class=\"toolbar\"><div class=\"filters\"><label class=\"sr-only\" for=\"project-filter\">项目</label><select id=\"project-filter\"><option value=\"\">全部项目</option></select><label class=\"search\">⌕ <input id=\"search\" placeholder=\"搜索事项、提出者、完成者\" aria-label=\"搜索事项\"></label></div><div><button id=\"history\">变更记录</button> <button id=\"add-project\" hidden>＋ 新建项目</button> <button id=\"add-task\" class=\"primary\" hidden>＋ 添加事项</button></div></div><div id=\"board\" class=\"board\"></div><div class=\"board-foot\"><span>按项目折叠 · 新事项默认置顶</span><span id=\"mode-hint\">当前为只读，可展开项目查看详情</span></div></section>\n<section id=\"accounts-view\" class=\"view workspace-view\" hidden>\n<div class=\"section-head\"><div><div class=\"eyebrow\">公有账号 · 02</div><h2>我的授权账号</h2><p>只显示你有权使用的账号，复制时会重新核对权限。</p></div><span id=\"accounts-count\" class=\"count-badge\"></span></div>\n<div class=\"account-filters\"><label>所属项目<select id=\"account-project\"><option value=\"\">全部项目</option></select></label><label class=\"account-search\">搜索账号<input id=\"account-search\" type=\"search\" placeholder=\"账号名称或项目名称\"></label></div>\n<div id=\"accounts\" class=\"account-grid\"></div></section>\n<section id=\"manage-view\" class=\"view workspace-view\" hidden>\n<div class=\"section-head\"><div><div class=\"eyebrow\">权限管理 · 03</div><h2>账号与授权</h2><p>账号默认进入公共池；选择项目可管理对应用户和专属链接。</p></div><div class=\"section-actions\"><button id=\"add-user\">添加用户…</button><button id=\"add-account\" class=\"primary\">添加公有账号…</button></div></div>\n<div class=\"project-context\"><label>当前管理项目<select id=\"manage-repo\"></select></label><button id=\"edit-project\">编辑项目资料…</button><span id=\"manage-context\"></span></div>\n<div class=\"management-grid\"><aside class=\"management-panel\"><div class=\"panel-heading\"><h3>默认账号池</h3><button id=\"select-all\">全选账号</button></div><p class=\"panel-hint\">勾选账号后拖入用户卡片，或点击该用户的“分配所选”。Shift 点击可连续选择。</p>\n<div class=\"management-toolbar\"><span id=\"selection-count\">已选 0 项</span><button id=\"grant-all\">分配给全部用户</button><button id=\"clear-all\">移除所选账号的全部授权</button><button id=\"delete-accounts\" class=\"danger\">删除所选账号</button></div><div id=\"pool\"></div></aside>\n<section class=\"management-panel\"><div class=\"panel-heading\"><h3>用户与权限</h3><div class=\"section-actions\"><button id=\"select-users\">全选用户</button><button id=\"delete-users\" class=\"danger\">删除所选用户</button></div></div><p class=\"panel-hint\">一个账号可分配给多位用户；移除授权不会删除账号或用户。</p><div id=\"users\" class=\"user-grid\"></div></section></div>\n<section class=\"token-section management-panel\"><div class=\"section-head\"><div><h2>专属访问链接</h2><p>访问链接即获得对应权限，无需输入链接。每条链接可单独调整权限或撤销。</p></div><div class=\"section-actions\"><button id=\"supervisor-link\" hidden>生成主管免登录链接</button><button id=\"issue-token\">配置新链接…</button></div></div><div id=\"tokens\"></div></section>\n<details class=\"storage-section\"><summary>数据同步与记录</summary><p id=\"storage-detail\"></p><button id=\"sync-github\" hidden>重试同步到 GitHub</button><button id=\"export-history\">导出公开历史</button><a href=\"/design.md\" download>下载设计细则</a><p id=\"identity-note\"></p></details></section>\n<footer><span>一起 / TEAM WORKSPACE</span><span>记录每一次推进。历史只增，不减。</span></footer></main>\n<dialog id=\"dialog\"><form id=\"form\"><div class=\"dialog-top\"><h2 id=\"dialog-title\"></h2><button type=\"button\" id=\"close-dialog\" aria-label=\"关闭\">×</button></div><div id=\"fields\"></div><p id=\"form-error\" role=\"alert\"></p><div class=\"dialog-actions\"><button type=\"button\" id=\"cancel\">取消</button><button id=\"save\" class=\"primary\" type=\"submit\">保存</button></div></form></dialog>\n<div id=\"toast\" role=\"status\"></div><script>window.BOARD_CONFIG={\"frontendUrl\":\"https://team-noticeboard-rebuilt.loneivy1.chatgpt.site/\"};\nfunction installPointerDrag({allowed,selectAccount,drop,describe}){\n let active=null,suppressClickUntil=0;const animations=new WeakMap();\n function reset(){document.querySelectorAll('.drop-target').forEach(n=>n.classList.remove('drop-target'));if(active?.frame)cancelAnimationFrame(active.frame)}\n function moveSlot(parent,before){const a=active;if(!a?.slot||a.slot.parentNode===parent&&a.slot.nextSibling===before)return;const selector=a.kind==='repo'?'.project-shell':'.task';const region=a.kind==='repo'?document.querySelector('#board'):a.source.closest('.project-shell');const nodes=[...(region||document).querySelectorAll(selector)].filter(n=>n!==a.source&&n!==a.ghost);const rects=new Map(nodes.map(n=>[n,n.getBoundingClientRect()]));parent.insertBefore(a.slot,before);for(const n of nodes){const old=rects.get(n);animations.get(n)?.cancel();const now=n.getBoundingClientRect(),dx=old.x-now.x,dy=old.y-now.y;if(Math.abs(dx)+Math.abs(dy)>1)animations.set(n,n.animate([{transform:`translate3d(${dx}px,${dy}px,0)`},{transform:'none'}],{duration:150,easing:'cubic-bezier(.2,.8,.2,1)'}))}}\n function targetAt(){const a=active;if(!a?.started)return;document.querySelectorAll('.drop-target').forEach(n=>n.classList.remove('drop-target'));const under=document.elementFromPoint(a.x,a.y);if(a.slot&&under?.closest('.drop-slot')===a.slot)return;a.target=null;\n if(a.kind==='task'){const body=under?.closest('.column-body');if(body&&body.dataset.repoId===a.source.dataset.repoId){const cards=[...body.querySelectorAll('article.task')].filter(n=>n!==a.source);let i=cards.findIndex(n=>a.y<n.getBoundingClientRect().top+n.getBoundingClientRect().height/2);if(i<0)i=cards.length;a.target={column:+body.dataset.column,order:cards.map(n=>n.dataset.id)};a.target.order.splice(i,0,a.id);a.dropElement=body;body.classList.add('drop-target');moveSlot(body,cards[i]||null)}}\n if(a.kind==='repo'){const project=under?.closest('.project-shell');if(project&&project!==a.source&&project.parentNode===a.originalParent){const after=a.y>project.getBoundingClientRect().top+project.getBoundingClientRect().height/2;a.target={repoId:project.dataset.repoId,after};a.dropElement=project;moveSlot(project.parentNode,after?project.nextSibling:project)}}\n if(a.kind==='account'){const user=under?.closest('.user-card');if(user){a.target={userId:user.dataset.user};a.dropElement=user;user.classList.add('drop-target')}}\n }\n function frame(){const a=active